      "selection": "Default ordinary software work; scope high-impact operations separately."
    },
    "CONTROLLED": {
      "selection": "Protected/high-impact boundary with explicit authority and actual qualification."
    }
  },
  "note": "Profiles select assurance, never authorization."
}

